update Toss_t 
set canceledAt=#{canceledAt}, payStatus="취소완료"
where t_idx=#{t_idx}

UPDATE User_t u
INNER JOIN Toss_t t ON u.id = t.id
SET u.payCount = u.payCount - #{statusCount}
WHERE t.t_idx = #{t_idx}

